#!/usr/bin/python3 -I
"""Print reviewable Incus preparation commands for a site; never run them.

The output is a bash script that creates one STOPPED system container and
one dedicated state volume per instance. Every container gets
boot.autostart=false, no nesting, no privileged mode and the site's
limits. The script refuses to adopt an existing instance or volume and
never boots or enters a container.
"""

from __future__ import annotations

import argparse
import json
import re
import shlex
import sys
from pathlib import Path

# -I drops the script directory from sys.path; add back only that directory.
sys.path.insert(0, str(Path(__file__).resolve().parent))
import sitefile

NAME_RE = re.compile(r"^[a-z][a-z0-9-]{0,62}$")
IMAGE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:/-]*$")
SIZE_RE = re.compile(r"^[1-9][0-9]*(MiB|GiB|TiB)$")


class IncusError(ValueError):
    pass


def _checked(pattern: re.Pattern, value: str, what: str) -> str:
    if not isinstance(value, str) or not pattern.match(value):
        raise IncusError(f"invalid {what} {value!r}")
    return value


def _conflicts(site: sitefile.Site, existing: dict | None) -> None:
    if existing is None:
        return
    taken = set(existing.get("instances", [])) | set(existing.get("volumes", []))
    for inst in site.instances:
        for name in (inst.name, f"{inst.name}-state"):
            if name in taken:
                raise IncusError(f"{name} already exists; refusing to adopt it")


def _preflight(site: sitefile.Site, p: str, image: str, pool: str) -> list[str]:
    q = shlex.quote
    count = len(site.instances)
    lines = [
        "#!/usr/bin/env bash",
        "# Generated by dist/edge/incus.py. Review, then run as root on the Incus host.",
        "set -euo pipefail",
        f"image_info=$(incus image info {q(image)})",
        "if [[ $image_info != *$'\\nType: container\\n'* ]]; then",
        "    echo 'a system container image is required, not a VM image' >&2; exit 1",
        "fi",
        f"containers=$(incus project get {p} limits.containers)",
        f"if [[ -z $containers || $containers -lt {count} ]]; then",
        f"    echo 'project {p} must set limits.containers to at least {count}' >&2; exit 1",
        "fi",
        f'echo "project {p} limits.memory: $(incus project get {p} limits.memory)"',
    ]
    for inst in site.instances:
        lines += [
            f"if incus --project {p} info {inst.name} >/dev/null 2>&1; then",
            f"    echo 'instance {inst.name} already exists; inspect it manually' >&2; exit 1",
            "fi",
            f"if incus storage volume show {pool} {inst.name}-state --project {p} >/dev/null 2>&1; then",
            f"    echo 'volume {inst.name}-state already exists; refusing to adopt state' >&2; exit 1",
            "fi",
        ]
    return lines


def _instance(
    site, inst, p: str, image: str, pool: str, volume_size: str | None
) -> list[str]:
    config = [
        "boot.autostart=false",
        "security.nesting=false",
        "security.privileged=false",
    ]
    if inst.cpu is not None:
        config.append(f"limits.cpu={inst.cpu}")
    if inst.memory is not None:
        config.append(f"limits.memory={inst.memory}")
    flags = " ".join(f"-c {c}" for c in config)
    lines = [
        f"incus --project {p} init {shlex.quote(image)} {inst.name} --storage {pool} {flags}"
    ]
    if inst.address is not None:
        key = "ipv6.address" if ":" in inst.address else "ipv4.address"
        lines.append(
            f"incus --project {p} config device override {inst.name} eth0 {key}={inst.address}"
        )
    size = f" size={volume_size}" if volume_size else ""
    mount = f"pool={pool} source={inst.name}-state path={shlex.quote(site.state_root)}"
    lines += [
        f"incus storage volume create {pool} {inst.name}-state --project {p}{size}",
        f"incus --project {p} config device add {inst.name} state disk {mount}",
    ]
    return lines


def commands(
    site: sitefile.Site,
    *,
    project: str,
    image: str,
    pool: str,
    volume_size: str | None = None,
    existing: dict | None = None,
) -> str:
    p = _checked(NAME_RE, project, "project")
    pool = _checked(NAME_RE, pool, "storage pool")
    image = _checked(IMAGE_RE, image, "image")
    if volume_size is not None:
        _checked(SIZE_RE, volume_size, "volume size")
    _conflicts(site, existing)
    lines = _preflight(site, p, image, pool)
    for inst in site.instances:
        lines += _instance(site, inst, p, image, pool, volume_size)
    lines += [
        f"incus --project {p} list --format csv -c ns4",
        "echo 'Prepared stopped containers. No workloads, credentials or receipts installed.'",
    ]
    return "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("site", type=Path)
    parser.add_argument("--project", required=True)
    parser.add_argument("--image", required=True, help="a system container image")
    parser.add_argument(
        "--pool", required=True, help="storage pool for the state volumes"
    )
    parser.add_argument("--volume-size", help="state volume size, e.g. 64GiB")
    parser.add_argument(
        "--existing", type=Path, help='JSON {"instances": [...], "volumes": [...]}'
    )
    args = parser.parse_args()
    try:
        site = sitefile.load(args.site)
        existing = json.loads(args.existing.read_text()) if args.existing else None
        text = commands(
            site,
            project=args.project,
            image=args.image,
            pool=args.pool,
            volume_size=args.volume_size,
            existing=existing,
        )
    except (sitefile.SiteError, IncusError, OSError, ValueError) as err:
        print(f"incus: {err}", file=sys.stderr)
        return 2
    sys.stdout.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())
